// Generated by ClawHub's actual runBundledSkillSpector producer using its
// minimized partial fixture and an explicitly complete child, not aggregate counters.
func TestClawHubBundledPartialReachesJudge(t *testing.T) {
	raw, err := os.ReadFile("testdata/skillspector-bundled-partial.json")
	if err != nil {
		t.Fatal(err)
	}
	target := t.TempDir()
	for name, content := range map[string]string{
		"openclaw.plugin.json":  `{"id":"bundle-fixture"}`,
		"skills/alpha/SKILL.md": "# Alpha\nRead tool.js for runtime behavior.\n",
		"skills/alpha/tool.js":  "// Inert fixture for a dynamic-import inspection gap.\n",
		"skills/beta/SKILL.md":  "# Beta\nInert complete child.\n",
	} {
		path := filepath.Join(target, filepath.FromSlash(name))
		if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
			t.Fatal(err)
		}
	}
	path := filepath.Join(t.TempDir(), "report.json")
	if err := os.WriteFile(path, raw, 0o600); err != nil {
		t.Fatal(err)
	}
	prompt, err := os.ReadFile("../profiles/clawhub/prompt.md")
	if err != nil {
		t.Fatal(err)
	}
	command := &recordingCommandRunner{}
	command.runHook = func(_ string, _ []string, workspace string) error {
		rendered, err := os.ReadFile(filepath.Join(workspace, "prompt.md"))
		if err != nil || !bytes.Contains(rendered, []byte("bundled_reports")) || !bytes.Contains(rendered, []byte("rootPath")) {
			t.Fatalf("prompt lost bundled source mapping: err=%v", err)
		}
		report, err := os.ReadFile(filepath.Join(workspace, "skillspector-report-0.json"))
		if err != nil || !bytes.Equal(report, raw) || !bytes.Contains(report, []byte("dynamic_import")) {
			t.Fatalf("judge lost original bundled reports/gaps: err=%v", err)
		}
		if _, err := os.ReadFile(filepath.Join(workspace, "artifact", "skills", "alpha", "tool.js")); err != nil {
			return err
		}
		receipt := partialJudgeReceipt(t, workspace)
		files := receipt["files_inspected"].([]string)
		receipt["version"], receipt["required_file"] = 2, files[0]
		receipt["additional_files_inspected"] = []string{"artifact/skills/alpha/tool.js"}
		delete(receipt, "files_inspected")
		command.writeOutput = string(judgeRetryOutput(t, map[string]any{
			"verdict": "benign", "artifact_inspection": receipt,
			"user_guidance": "Inspected alpha/tool.js for the material import gap; scanner uncertainty remains recorded.",
		}).Stdout)
		return nil
	}
	artifact, err := Run(Options{
		Profile: "clawhub", Target: target, Scanners: []string{"skillspector"},
		ScannerResultPaths: map[string]string{"skillspector": path},
		Judge:              &JudgeOptions{Command: "judge --prompt {{ prompt:clawhub/prompt.md }} --output {{ output }}", Files: map[string][]byte{"clawhub/prompt.md": prompt}},
		GateRules:          map[string]ScannerGatePolicy{"skillspector": {JSONRules: []JSONGateRule{{ID: "retained-bundle-finding", Paths: []string{"filtered_findings[].severity"}, Equals: json.RawMessage(`"HIGH"`), Action: "warn"}}}},
	}, RunContext{Env: map[string]string{}, CommandRunner: command})
	if err != nil {
		t.Fatal(err)
	}
	result := artifact.Scanners["skillspector"]
	if !artifact.Complete || artifact.Judge == nil || artifact.Judge.Status != "completed" || result.Status != "partial" || result.ReportPolicy != "judge-gaps" || !bytes.Equal(result.Raw, raw) {
		t.Fatalf("bundled partial did not reach adjudication: status=%s complete=%v scanner=%s judge=%+v", artifact.Status, artifact.Complete, result.Status, artifact.Judge)
	}
	if artifact.Gate != "warn" || len(artifact.GateRules) != 1 {
		t.Fatalf("aggregate findings bypassed gate: %s %+v", artifact.Gate, artifact.GateRules)
	}
	if !strings.Contains(string(prompt), "skillspector-report-0.json") {
		t.Fatal("prompt does not point to full raw evidence")
	}
}

func TestClawHubBundledPartialCompleteChildEvidence(t *testing.T) {
	fixture, err := os.ReadFile("testdata/skillspector-bundled-partial.json")
	if err != nil {
		t.Fatal(err)
	}
	for _, test := range []struct {
		name, child, want string
	}{
		{"issues-only", `{"issues":[]}`, "failed"},
		{"risk-status-only", `{"status":"clean","issues":[]}`, "failed"},
		{"missing-root-execution", `{"issues":[],"analysis_completeness":{"execution_successful":true,"is_complete":true}}`, "failed"},
		{"missing-accounting", `{"issues":[],"execution_successful":true}`, "failed"},
		{"missing-accounting-execution", `{"issues":[],"execution_successful":true,"analysis_completeness":{"is_complete":true}}`, "failed"},
		{"missing-completion", `{"issues":[],"execution_successful":true,"analysis_completeness":{"execution_successful":true}}`, "failed"},
		{"explicit-completion", `{"issues":[],"execution_successful":true,"analysis_completeness":{"execution_successful":true,"is_complete":true}}`, "partial"},
	} {
		t.Run(test.name, func(t *testing.T) {
			var report map[string]any
			if err := json.Unmarshal(fixture, &report); err != nil {
				t.Fatal(err)
			}
			rows := report["bundled_reports"].([]any)
			rows[1].(map[string]any)["report"] = json.RawMessage(test.child)
			assertBundledScannerStatus(t, mustMarshalBundleValue(t, report), test.want)
		})
	}
	// Legacy complete reports remain accepted outside the new partial wrapper.
	for _, profile := range []string{"", "custom", "clawhub", "clawhub-aig"} {
		t.Run("legacy-standalone/"+profile, func(t *testing.T) {
			raw := `{"issues":[]}`
			command := &recordingCommandRunner{writeOutput: raw, exitCode: intPointer(0)}
			result, err := (ExternalScannerRunner{Profile: profile, CommandRunner: command, Env: map[string]string{}, SkillSpectorCommand: []string{"skillspector"}}).runSkillSpector(t.TempDir(), "now")
			if err != nil || result.Status != "completed" || result.ReportPolicy != "" || string(result.Raw) != raw {
				t.Fatalf("legacy complete changed: status=%s policy=%s err=%v", result.Status, result.ReportPolicy, err)
			}
		})
	}
}

func TestClawHubBundledPartialRejectsAmbiguousEvidence(t *testing.T) {
	fixture, err := os.ReadFile("testdata/skillspector-bundled-partial.json")
	if err != nil {
		t.Fatal(err)
	}
	for _, test := range []struct {
		name, section, field string
		value                any
	}{
		{"missing-roots", "wrapper", "bundled_reports", nil},
		{"empty-roots", "wrapper", "bundled_reports", []any{}},
		{"root-not-object", "wrapper", "bundled_reports", []any{false}},
		{"unsuccessful-wrapper", "wrapper", "execution_successful", false},
		{"malformed-risk-status", "wrapper", "status", 42},
		{"failed-wrapper", "wrapper", "status", "failed"},
		{"wrapper-error", "wrapper", "error", "scanner crashed"},
		{"wrapper-error-type", "wrapper", "error", false},
		{"wrapper-case-conflict", "wrapper", "Execution_successful", false},
		{"unknown-wrapper-field", "wrapper", "future", true},
		{"malformed-risk", "wrapper", "risk_assessment", []any{}},
		{"invalid-findings", "wrapper", "filtered_findings", []any{false}},
		{"failed-accounting", "accounting", "execution_successful", false},
		{"complete-by-synthesis", "accounting", "is_complete", true},
		{"accounting-alias", "accounting", "Status", "failed"},
		{"nested-bundle", "partial", "bundled_reports", []any{}},
		{"nested-bundle-alias", "partial", "bundledReports", []any{}},
		{"crashed-child", "partial", "execution_successful", false},
		{"child-case-conflict", "partial", "Execution_successful", false},
		{"fatal-child", "partialAccounting", "ledger_exceptions", []any{map[string]any{"fatal": true}}},
		{"fatal-alias", "partialAccounting", "ledger_exceptions", []any{map[string]any{"fatal": false, "Fatal": true}}},
		{"unknown-typed-gap", "partialAccounting", "limitations", false},
		{"failed-complete-child", "complete", "status", "failed"},
		{"complete-error", "complete", "error", true},
		{"complete-case-conflict", "complete", "Status", "failed"},
		{"complete-fatal", "complete", "analysis_completeness", map[string]any{"execution_successful": true, "is_complete": true, "ledger_exceptions": []any{map[string]any{"fatal": true}}}},
		{"complete-findings-type", "complete", "issues", false},
		{"complete-metadata-type", "complete", "metadata", false},
		{"complete-components-type", "complete", "components", false},
		{"duplicate-root", "entry", "rootPath", "skills/beta"},
		{"path-case-conflict", "entry", "RootPath", "../escape"},
		{"child-case-conflict-report", "entry", "Report", map[string]any{"status": "clean", "issues": []any{}}},
		{"unknown-entry-field", "entry", "future", true},
		{"child-scalar", "entry", "report", true},
		{"empty-child", "entry", "report", map[string]any{}},
		{"no-partial-child", "entry", "report", map[string]any{"status": "clean", "issues": []any{}, "execution_successful": true, "analysis_completeness": map[string]any{"execution_successful": true, "is_complete": true}}},
	} {
		t.Run(test.name, func(t *testing.T) {
			var report map[string]any
			if err := json.Unmarshal(fixture, &report); err != nil {
				t.Fatal(err)
			}
			rows := report["bundled_reports"].([]any)
			partial := rows[0].(map[string]any)["report"].(map[string]any)
			sections := map[string]map[string]any{
				"wrapper": report, "accounting": report["analysis_completeness"].(map[string]any),
				"entry": rows[0].(map[string]any), "partial": partial,
				"partialAccounting": partial["analysis_completeness"].(map[string]any),
				"complete":          rows[1].(map[string]any)["report"].(map[string]any),
			}
			sections[test.section][test.field] = test.value
			raw, err := json.Marshal(report)
			if err != nil {
				t.Fatal(err)
			}
			assertBundledScannerStatus(t, raw, "failed")
		})
	}
	for _, root := range []string{"", ".", "..", "../skills", "/skills/alpha", "skills/../alpha", "skills//alpha", "skills/alpha/", "skills\\alpha", "skills/\x00alpha"} {
		t.Run("path/"+root, func(t *testing.T) {
			raw := bytes.Replace(fixture, []byte(`"rootPath": "skills/alpha"`), []byte(`"rootPath": `+string(mustMarshalBundleValue(t, root))), 1)
			assertBundledScannerStatus(t, raw, "failed")
		})
	}
	duplicate := bytes.Replace(fixture, []byte(`"execution_successful": true`), []byte(`"execution_successful": false, "execution_successful": true`), 1)
	assertBundledScannerStatus(t, duplicate, "failed")
}

func mustMarshalBundleValue(t *testing.T, value any) []byte {
	t.Helper()
	raw, err := json.Marshal(value)
	if err != nil {
		t.Fatal(err)
	}
	return raw
}

func assertBundledScannerStatus(t *testing.T, raw []byte, want string) {
	t.Helper()
	path := filepath.Join(t.TempDir(), "report.json")
	if err := os.WriteFile(path, raw, 0o600); err != nil {
		t.Fatal(err)
	}
	result, err := scannerResult(Options{Profile: "clawhub", ScannerResultPaths: map[string]string{"skillspector": path}}, "skillspector", resolvedTarget{}, "now", nil)
	if err != nil || result.Status != want || !bytes.Equal(result.Raw, raw) || want == "failed" && result.ReportPolicy != "" {
		t.Fatalf("status=%s want=%s policy=%s err=%v", result.Status, want, result.ReportPolicy, err)
	}
}

func TestClawHubBundledPartialRiskAndCommandContract(t *testing.T) {
	fixture, err := os.ReadFile("testdata/skillspector-bundled-partial.json")
	if err != nil {
		t.Fatal(err)
	}
	for _, risk := range []string{"clean", "suspicious", "malicious"} {
		t.Run(risk, func(t *testing.T) {
			raw := bytes.Replace(fixture, []byte(`"status": "suspicious"`), []byte(`"status": "`+risk+`"`), 1)
			assertBundledScannerStatus(t, raw, "partial")
		})
	}
	for _, profile := range []string{"", "custom", "clawhub", "clawhub-aig"} {
		for _, exit := range []int{0, 1, 2} {
			command := &recordingCommandRunner{writeOutput: string(fixture), exitCode: intPointer(exit)}
			if exit != 0 {
				command.err = errCommandFailed
			}
			result, err := (ExternalScannerRunner{Profile: profile, CommandRunner: command, Env: map[string]string{}, SkillSpectorCommand: []string{"skillspector"}}).runSkillSpector(t.TempDir(), "now")
			want := "failed"
			if (profile == "clawhub" || profile == "clawhub-aig") && exit < 2 {
				want = "partial"
			}
			if err != nil || result.Status != want || !bytes.Equal(result.Raw, fixture) {
				t.Fatalf("profile=%s exit=%d status=%s want=%s err=%v", profile, exit, result.Status, want, err)
			}
			if want == "partial" && result.Error != "" {
				t.Fatalf("accepted native exit still fails consumer operational-error check: exit=%d error=%s", exit, result.Error)
			}
		}
	}
}
